import { useContext,useSate, useState } from "react";
import classes from "./UserForm.module.css";
import PasswordContext from "../store/password-context";


const UserForm = ({ onEditItem, editingItem }) => {
  const [title, setTitle] = useState(editingItem ? editingItem.title : "");
  const [password, setPassword] = useState(
    editingItem ? editingItem.password : ""
  );

  const titleHandler = (event) => {
    setTitle(event.target.value);
  };

  const passwordHandler = (event) => {
    setPassword(event.target.value);
  };

  const submitHandler = (event) => {
    event.preventDefault();
    const id = Date.now() + Math.random().toString(36).substring(2);

    const item = {
      id: id,
      title: title,
      password: password,
    };

    if (editingItem) {
      onEditItem(item);
    } else {
      // Add new item
    }

    // Reset form fields
    setTitle("");
    setPassword("");
  };

  const closeFormhandler = () => {
    // Close the form
  };

  return (
    <div>
      <div className={classes.form}>
        <form onSubmit={submitHandler}>
          <label>Title :</label>
          <input
            type="text"
            name="title"
            value={title}
            onChange={titleHandler}
            required
          ></input>
          <label>Password:</label>
          <input
            type="text"
            name="password"
            value={password}
            onChange={passwordHandler}
            required
          ></input>

          <button type="submit">Save</button>
          <button onClick={closeFormhandler}>Cancel</button>
        </form>
      </div>
    </div>
  );
};

export default UserForm;
